import{_ as e,p as r,q as a,s as t,R as o,t as u,Y as s,n as q}from"./framework-e1bed10d.js";const n="/my-blog/assets/004_01-701854c1.png",p="/my-blog/assets/004_02-9488c8fa.png",c="/my-blog/assets/004_03-c5c20efd.png",h="/my-blog/assets/004_04-4dce02e2.png",i={},_=t("h1",{id:"信贷的定义与分类",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#信贷的定义与分类","aria-hidden":"true"},"#"),o(" 信贷的定义与分类")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484159&idx=1&sn=e19e853ed5de87f36b146c71eb1d5856&chksm=e8c6f283dfb17b954ce3ae760950c3047dd93530f2c1f859980cbe62bfd5e22eb5afb15d5a09",target:"_blank",rel:"noopener noreferrer"},g=s('<hr><p>信贷不就是&quot;借钱、收钱、控风险&quot;吗？这是很多程序员接手信贷系统时的第一印象。可一旦坐进需求会，你很快会发现这三个词远远不够。信贷的商业逻辑千头万绪，但抽干了就三个字：资金、风险、收益。资金是这门生意靠什么运转，风险是这门生意最怕什么，收益是这门生意凭什么活下去。</p><p>这一章不讲代码，不画架构图，只讲一件事：信贷到底是一门怎样的生意。把它讲透了，后面所有章节才有了站得住脚的地基。</p><h2 id="一、信贷的定义与分类" tabindex="-1"><a class="header-anchor" href="#一、信贷的定义与分类" aria-hidden="true">#</a> 一、信贷的定义与分类</h2><h3 id="一-先给信贷一个能落进代码的定义" tabindex="-1"><a class="header-anchor" href="#一-先给信贷一个能落进代码的定义" aria-hidden="true">#</a> （一）先给信贷一个能落进代码的定义</h3><p>先给信贷一个业内公认的定义：银行等金融机构利用自身实力和信誉为客户提供资金融通和承担债务的行为，并以客户支付融通资金的利息、费用或最终承担债务为条件。这个定义看起来绕，但拆开看就是三句话。</p><p>第一句，&quot;利用自身实力和信誉&quot;。实力，就是手里有钱，或者能从市场上低成本地融到钱；信誉，就是被金融市场认可，借来的钱别人敢给、给了还不担心你还不上。这两个词，才是信贷这门生意真正的门槛，不是谁都做得起放贷生意，你得先有这两样东西。你在系统里看到的所有&quot;资金路由&quot;&quot;负债管理&quot;&quot;同业拆借&quot;模块，本质都在解决&quot;实力&quot;这两个字；而&quot;信誉&quot;这两个字，落在系统里就是资本充足率、拨备覆盖、监管评级这些看起来跟业务无关的合规字段。</p><p>第二句，&quot;资金融通和承担债务&quot;。这句话最容易被忽略，也最值得程序员琢磨。资金融通是&quot;贷款&quot;，把钱借出去；承担债务则是另一类业务，银行开承兑汇票、开保函、开信用证，本身没有把钱借出去，而是用自己的信誉为客户的债务做担保，客户到期还不上，银行要替他还。这两类业务在会计上一个记表内、一个记表外，在系统里一个生成贷款账户、一个生成担保合同和或有负债记录，形态完全不同。你写系统的第一天就得分清楚：你面对的是&quot;融出去的钱&quot;，还是&quot;背上的债&quot;。</p><p>第三句，&quot;以利息、费用或最终承担债务为条件&quot;。这句话点明了信贷的盈利本质，银行不是慈善机构，提供融通是要收费的，收费方式无非三种：收利息、收费用、或者最终替客户承担债务后追偿。这也就是后面要讲的&quot;利差收入、服务费收入&quot;的来源。</p><p>光讲定义容易飘，我给你一个把它落到地上的例子。你身边一个年轻人想买一辆二十万的车，手头只有八万，于是他向银行申请一笔十二万的车贷。在这个场景里，银行做的是&quot;资金融通&quot;，把钱借出去十二万；条件是年轻人按月还本付息，付的利息就是银行的&quot;利息收入&quot;；为了降低风险，银行要求这辆车抵押登记，这就是&quot;担保&quot;；如果年轻人信用不够，银行可能要求一家担保公司出面保证，这就是&quot;增信&quot;。这一笔看起来普通的车贷，背后其实是资金、风险、收益三角在真实世界的第一次咬合。而系统里要为它建的，是一张客户档案、一份借款合同、一张抵押登记记录、一份还款计划、一张贷款账户，缺一张，这笔贷款就立不住。</p><p>再往深里说一层。信贷定义的三个要点，恰好对应信贷系统里三个最底层的模块（见图 1-1）。一个定义，三个要点，三套系统模块，这就是&quot;业务怎么算，系统就怎么做&quot;最直接的体现。</p><p><img src="'+n+'" alt="图片"></p><p>从程序员的角度看，这个定义其实在告诉你要建几张表。信贷的实质是一组契约关系：主合同（借款合同）约定借贷双方的权利义务，借据（借据/借约）是每一笔具体放款的凭据，担保合同（保证、抵押、质押、保证金）是第二还款来源的约定，额度协议则是&quot;给你一个可以循环使用的上限&quot;。把信贷画成领域模型，&quot;合约主题&quot;下面会挂着一串对象：贷款主合约、担保合同-从合约、贷款账户信息、合约费用、合约生命周期。这就是信贷在系统里的样子，它不是一句&quot;借钱&quot;的日常口语，而是一张严密的主从合同关系网。后面第四章讲领域建模时，你会看到信贷核心的数据模型，就是围绕&quot;主合同—从合同—借据—账户&quot;这四件套展开的。</p><p>定义讲完，我把信贷的&quot;基本要素&quot;也一并交代了，因为它和定义是一体两面。一笔信贷业务，掰开就是六个要素（见图 1-2）。你把这六个要素想成一张&quot;信贷合同的最小字段集&quot;，任何一笔贷款，系统里都得有这六项，缺一项，这笔贷款就不完整、不合法、不可管理。业务上的&quot;基本要素&quot;，就是系统里的&quot;必填字段&quot;，它们不是一个概念，是同一件事的两面。下面讲分类时你会发现，分类其实就是这六个要素在不同维度上的取值组合。</p><p><img src="'+p+'" alt="图片"></p><p><strong>图1-2一笔信贷业务的六个基本要素（最小字段集）</strong></p><h3 id="二-信贷的分类-每一刀都切在系统的对象模型上" tabindex="-1"><a class="header-anchor" href="#二-信贷的分类-每一刀都切在系统的对象模型上" aria-hidden="true">#</a> （二）信贷的分类：每一刀都切在系统的对象模型上</h3><p>信贷分类的体系很成熟，我结合系统视角重新梳理一遍，你会发现一个规律：业务上每分一次类，系统里就多一个维度、多一组字段、多一套规则。这句话我建议你读三遍，它是从业务到系统最直接的翻译规则。业务人员谈&quot;分类&quot;，谈的是认识贷款的角度；程序员听&quot;分类&quot;，听到的是系统要管的维度。同一笔贷款，在业务会议上可能被讨论&quot;它是消费贷还是经营贷&quot;，在系统里它同时具有贷款对象、担保方式、期限、用途、还款方式、资金性质、合作方式、利率类型、币种九个维度，不是一个标签，是六个字段的组合。下面我把这些分类一把一把讲清楚。</p><p>这里我要特别说一下&quot;按贷款对象&quot;这一维，它不是简单的&quot;对公vs对私&quot;二分法。除了这两个基本类，实际业务里还有四类特殊对象：小微企业/个体工商户、金融同业客户、政府类客户、产业链核心及上下游（见图 1-3）。每一类的业务特点和系统要求都不同，对应系统里单独的一套规则。</p><p><strong>图1-3 按贷款对象分类：不止对公和对私</strong></p><p><img src="'+c+'" alt="图片"></p><p>表<strong>1-1信贷产品谱系：分类维度×系统落点</strong></p><table><thead><tr><th><strong>分类维度</strong></th><th><strong>类别</strong></th><th><strong>系统落点</strong></th></tr></thead><tbody><tr><td>按贷款对象</td><td>个人贷款/ 对公贷款 / 小微企业·个体工商户 / 金融同业 / 政府类客户 / 产业链核心企业及上下游</td><td>客户域分个人/非自然/同业/政府类/产业链，对象模型与授信规则差异大</td></tr><tr><td>按担保方式</td><td>信用/ 保证 / 抵押 / 质押 / 保证金 / 组合担保</td><td>担保域实体不同，押品管理、估值频率、处置流程复杂度不同</td></tr><tr><td>按期限</td><td>短期（≤1年）/ 中期（1-5年）/ 长期（&gt;5年）</td><td>期限字段+ 利率参数 + 重定价规则 + 流动性管理</td></tr><tr><td>按用途</td><td>消费贷/ 经营贷 / 项目贷 / 按揭贷 / 供应链融资</td><td>用途字段+ 受托支付规则 + 资金用途监控，不同用途放款条件不同</td></tr><tr><td>按还款方式</td><td>等额本息/ 等额本金 / 先息后本 / 到期还本付息 / 灵活还款</td><td>还款计划生成引擎不同，现金流预测模型不同</td></tr><tr><td>按资金性质</td><td>表内/ 表外（承兑汇票/保函/信用证）</td><td>会计科目不同，表外要处理或有负债、出表与承诺</td></tr><tr><td>按合作方式</td><td>自营/ 助贷 / 联合贷 / ABS出表</td><td>资金路由、分账比例、增信对接、出表处理差异最大</td></tr><tr><td>按利率类型</td><td>固定利率/ 浮动利率（LPR挂钩）</td><td>利率重定价规则不同，利率风险计量与对冲方式不同</td></tr><tr><td>按币种</td><td>人民币/ 外币</td><td>结售汇、汇率风险、跨境监管报送不同</td></tr></tbody></table><h3 id="三-技术落点·分类背后-是对象模型的骨架" tabindex="-1"><a class="header-anchor" href="#三-技术落点·分类背后-是对象模型的骨架" aria-hidden="true">#</a> （三）技术落点·分类背后，是对象模型的骨架</h3><p>这一小节的落点很直接：信贷的每一种分类，最后都要变成系统对象模型里的一个字段或一组关系。信贷系统的领域模型整张图，其实就是把这些分类落成了实体和关系，分为五大核心域、支撑服务域和基础设施层（见图 1-4）。</p><p><img src="'+h+'" alt="图片"></p><p>我给刚入行的同事讲系统设计时常说一句话：先别急着写代码，先把&quot;这是一笔什么贷款&quot;问清楚。是个人还是对公？是信用还是抵押？是表内还是表外？是短期还是长期？是等额本息还是先息后本？是自营还是助贷？这一串问题问完，系统的模块划分、表结构、状态机设计基本就浮出水面了。九个维度，九个模块，一一对应。商业逻辑不是&quot;做完业务再补&quot;的东西，它本身就是系统设计的第一输入。</p>',27);function b(m,f){const d=q("ExternalLinkIcon");return r(),a("div",null,[_,t("blockquote",null,[t("p",null,[o("公众号：侃西东　·　发布日期：2026-09-16　·　"),t("a",l,[o("微信原文"),u(d)])])]),g])}const k=e(i,[["render",b],["__file","004.html.vue"]]);export{k as default};
